export const LESSONS = {"rows":{"topicId":"mt_UTnDKQkVX5","title":"怎样铺得整整齐齐","formal":"长方形的行列与方阵","summary":"每个小方格一样大，没有空隙和重叠。每行几格、共有几行，描述同一个方阵；逐个数、按行累加与相乘能得到同一个总数。","reflection":"为什么每行都一样长？加一行会多几格？","batch":"B02"},"solids":{"topicId":"mt_Mnodea7mG_","title":"转过去，还少数了什么","formal":"立体的面、棱和顶点","summary":"面是平的表面，棱是两个面相接的线段，顶点是棱相遇的点。转动后，原来被挡住的部分也要计入；逐项标记能避免重复。","reflection":"长方体拉长后，面、棱、顶点的个数会变吗？","batch":"B02"},"nets":{"topicId":"mt_vnJEztczji","title":"这张纸能合成盒子吗","formal":"正方体的展开图","summary":"六个正方形要能折到六个不同方向，不能重叠或缺面。样子陌生的展开图也可能成立，六格排在一起却不一定能合成立方体。","reflection":"你画的展开图里，哪两面相对？六格排成两行为什么不行？","batch":"B02"},"attributes":{"topicId":"mt_NtJYlJdUe9","title":"大的就一定重吗","formal":"可测量的属性","summary":"同一个物体可以比较长短、高矮、轻重和能装多少。这是不同的问题：较高的瓶子不一定较重，也不一定装得较多。","reflection":"一支铅笔能量什么？一个瓶子又能从哪几个方面比较？","batch":"B02"},"measure":{"topicId":"mt_DOe893F6gN","title":"挑对工具再量一量","formal":"标准单位与测量工具","summary":"尺量长度，秤量质量，量杯量容量。读数必须配上合适的单位；尺的零点要对准物体起点。这里练习模拟读数，真实器具还要实际操作。","reflection":"为什么尺子的端点不一定是零点？要量多少水，该选哪件工具？","batch":"B02"},"area":{"topicId":"mt_y1n0Zwhoca","title":"这片地方要铺几块","formal":"用单位正方形量面积","summary":"面积是里面铺满多少个相同的单位正方形。边上的格子也属于里面，凹口外的格子不属于；沿边绕一圈的长度是另一回事。","reflection":"L 形的缺口为什么不数？边缘格子为什么仍然要数？","batch":"B02"},"tiling":{"topicId":"mt_Jvvh5P06NV","title":"铺一排，再铺一排","formal":"铺面与乘法","summary":"每排有相同数量的方片。行数乘每行方片数，等于逐排累加；转动整片区域，面积保持不变。","reflection":"为什么 4 排每排 6 块与 6 排每排 4 块覆盖一样多？","batch":"B02"},"rectangle":{"topicId":"mt_GzcJEVkNRn","title":"长和宽能告诉什么","formal":"长方形面积","summary":"长和宽分别告诉一排有多少单位方片、共有几排，所以面积等于长乘宽。结果用平方单位；不同长宽也可以有相同面积。","reflection":"你能画出几个面积 36 的不同长方形？为什么不用长加宽？","batch":"B02"},"boundary":{"topicId":"mt_eiB3-6pu6a","title":"铺地和围边一样吗","formal":"长方形面积与周长","summary":"面积计算铺满里面的平方单位；周长计算围边的长度。知道长和面积能反求宽。不规则区域可以按约定的半格规则估计，这不是精确面积。","reflection":"同样面积的长方形，围边可以不同吗？池塘的估计为何可能有误差？","batch":"B02"},"capacity":{"topicId":"mt_NSC3LT_-ch","title":"看起来能装多少","formal":"容量估计与实际盛装量","summary":"容量是装满时能容纳的量，当前装了多少可以改变。1 L = 1000 mL；容量 1 L 的壶只装半壶时，里面有 500 mL。先估计，再量，估计不必刚好。","reflection":"一个半满的 1 升壶，容量和当前水量分别是多少？","batch":"B02"},"equalparts":{"topicId":"mt_Xp-rj46S2w","title":"样子不同，分到的一样多吗","formal":"等分与等量","summary":"平均分看每份的量是否相同，不只看轮廓。圆的三份各占相同角度，方格图里每份覆盖相同格数。","reflection":"长条和方块为什么都能是四分之一？","batch":"B03"},"notation":{"topicId":"mt_vKcxX6iNOA","title":"给取出的这份写个名字","formal":"分数的记法与分类","summary":"分母表示一个整体分成多少等份，分子表示取了多少份。单位分数也是一种真分数；达到一个整体的是假分数，整份加零头可以写成带分数。","reflection":"5/4 和 1 又 1/4 为什么描述同一个量？","batch":"B03"},"folds":{"topicId":"mt_gC-6JXAG5S","title":"再对折一次会怎样","formal":"二分之一、四分之一与八分之一","summary":"每次对折把每份再一分为二：份数加倍，每份减半。2/8 与 1/4 占同一个整体的相同面积。这里是折痕模拟，真实纸张可再动手核对。","reflection":"圆和方形都能取八分之一，整体变了，八分之一的意思变了吗？","batch":"B03"},"amounts":{"topicId":"mt_cFltwUQi-d","title":"一份到底是多少","formal":"数量、面积和长度的分数","summary":"找 12 个的三分之一，先把全部平均分成三组，再取一组。图形和线段也先确定整体、平均分、再取所需份数。","reflection":"为什么 12 个的三分之一是 4，而不是 3？","batch":"B03"},"fractionline":{"topicId":"mt_NoB20kVa4w","title":"从零走到这一份","formal":"数轴上的分数","summary":"把 0 到 1 分成 b 段，每段是 1/b；a/b 是从零走 a 段。分四段只需要三个内部刻度，数的是间隔而不是点。","reflection":"1/3 和 1/6，哪一步更长？为什么？","batch":"B03"},"visualeq":{"topicId":"mt_FbDKeLfBCo","title":"分法变了，量变了吗","formal":"等值分数的面积表示","summary":"同样长的整体，涂色末端对齐就表示相同的量。每份继续等分时，取的份数和总份数一起改变；只改一个数通常会改变量。","reflection":"2/3 和 4/6 一样多，那 2/6 呢？","batch":"B03"},"hundredths":{"topicId":"mt_doX1BhmFgk","title":"把一小格再分十份","formal":"百分之一","summary":"一个整体的十分之一再分成十份，每小份是百分之一。十个百分之一才组成一个十分之一，数过 10/100 还能继续到 11/100、12/100。","reflection":"为什么分成的份数更多，每一份反而更小？","batch":"B03"},"decpercent":{"topicId":"mt_W17Kbwm0-u","title":"同一个量，三种写法","formal":"小数、分数与百分数","summary":"小数点前是整份，后面依次是十分位、百分位。百分数把整体看成 100 份：1/2 = 0.5 = 50%。同一整体的量不因记法改变。","reflection":"0.09 为什么是 9%，不是 90%？","batch":"B03"},"scale":{"topicId":"mt_VKW8lOcFaw","title":"乘完一定变大吗","formal":"乘法作为缩放","summary":"对正数，乘大于 1 的正数变大，乘小于 1 的正数变小，乘 1 不变。n/n 等于 1，分数上下同乘 n 只改变分法。","reflection":"先不算结果，怎样判断乘 3/4 后会变大还是变小？","batch":"B03"},"ratios":{"topicId":"mt_ePXg_XyCKU","title":"按两种颜色来分","formal":"比的条形模型","summary":"3:2 是三块与两块，每块一样大。先用总量除以总块数，再求两边各有多少。条形看份数，表格查数值，双数轴看两个量一起变化。","reflection":"为什么按 3:2 分 20，要先分成 5 份，而不是 3 份？","batch":"B03"},"sortobjects":{"topicId":"mt_xppl18avyY","title":"换个办法分一分","formal":"按属性分类","summary":"分类要始终使用同一个规则。相同一堆物品，按颜色和按大小分，可以得到不同的数量。比较多少要看数量，不能只看物体占多大地方。","reflection":"换一种分类后，物品总数变了吗？","batch":"B04"},"sortdata":{"topicId":"mt_ylXdiVRAYv","title":"让零散回答排好队","formal":"分类与频数表","summary":"每个回答只进一个类别。各类次数加起来应等于回答总数；按数量排序后更容易比较，有并列时不必硬分先后。","reflection":"新增两个回答后，哪一行要改？总数怎样核对？","batch":"B04"},"statquestions":{"topicId":"mt_iykH2P5oFq","title":"这个问题需要去收集吗","formal":"统计问题与数据变异","summary":"统计问题需要从一组观察中寻找答案，并预期结果可能不同。观察可以来自不同人，也可以是同一个人在不同日子的记录；已知固定答案不需要这种调查。","reflection":"把“我今天读了几分钟”改成能研究变化的问题，会怎样问？","batch":"B04"},"datavocab":{"topicId":"mt_u5HkSxZECM","title":"图里的每个位置管什么","formal":"图表要素与数据类型","summary":"标题交代问什么，轴标记类别和数量，刻度说明每格代表多少。次数叫频数；计数笔画和图形可以表示同样次数。人数可逐个数，长度和时间能有中间值。","reflection":"身高写成整数，就变成只能逐个数的量了吗？","batch":"B04"},"scaledgraphs":{"topicId":"mt_r8XnXwRA6g","title":"一个图案可以代表几个","formal":"有比例刻度的图表","summary":"先读每格或每个图案代表多少，再读数量。换刻度，表达相同数据时柱子高度也要跟着变。","reflection":"一格代表 5 只宠物，四格代表几只？","batch":"B04"},"displaypurpose":{"topicId":"mt_QpJydot2Kh","title":"换张图，哪个问题更好答","formal":"按目的选择数据表示","summary":"同一份记录可以用表格或条形图。表格便于查精确值，条形便于看差距；转换时类别与数量不能改变。选择要联系你想回答的问题。","reflection":"你想查一个人数，或想一眼比出最多，分别会怎样选？","batch":"B04"},"likelihood":{"topicId":"mt_iFFKZd-Vgv","title":"很可能，是一定吗","formal":"可能性语言","summary":"不可能表示没有这种结果，一定表示只能出现这种结果。大多数是红色只能说明红色更可能，仍可能抽到蓝色；有两种结果也不一定各占一半。","reflection":"袋里七红三蓝，为什么抽红不是一定？","batch":"B04"},"chance":{"topicId":"mt_J4j7d3iAfg","title":"先猜，再一次次记录","formal":"简单随机试验","summary":"先预测，再一次一笔记录试验。总次数应对得上各类次数。公平的硬币并不保证每二十次恰好十正十反；这里做的是数字模拟。","reflection":"这次结果与预测不同，是记录错了还是可能正常发生？","batch":"B04"},"fairness":{"topicId":"mt_xSgAgg9Ej_","title":"机会一样，要看什么","formal":"等可能与不等可能","summary":"在理想均匀转盘中，机会取决于每种颜色占的角度。颜色数量相同不等于面积相同；实验次数有波动，不能靠少数几次判断规则。","reflection":"只有红蓝两色，就一定是五五开吗？","batch":"B04"},"simulation":{"topicId":"mt_8DT3LXwwH-","title":"试得更多，会更稳吗","formal":"数字模拟与频率波动","summary":"把每轮出现六的次数除以该轮总次数，才能比较不同规模。更多试验通常使比例更集中在 1/6 附近，但不保证每一轮更接近，也不会保证恰好等于 1/6。","reflection":"为什么不能只比较出现六的次数？哪种结果会推翻“每次都更接近”？","batch":"B04"},"repeat":{"topicId":"mt_ZjIFGc6zPW","title":"是哪一小段一直回来","formal":"重复单元","summary":"重复规律由一个最小单元反复组成。材料可以换成图形、数字或动作，位置关系仍然保持。","reflection":"只看下一个是什么，和找出整段重复单元，有什么不同？","batch":"B05"},"structure":{"topicId":"mt_DW2D1c0fKx","title":"换了样子，什么没变","formal":"运算与图形的结构","summary":"交换加数位置，总数不变；加一个十改变十位的量，个位不变。长方形和正方形都有四条边、四个直角，正方形还要求四边一样长。","reflection":"为什么 47 加 10 不需要重新逐个数 47 颗？","batch":"B05"},"growing":{"topicId":"mt_W3VOAuFwVw","title":"每次多一点，会长到哪里","formal":"固定步长的增长与减少","summary":"采用固定步长时，从起点不断加上或减去相同数量，就能构造后续项。这里只研究约定的固定变化；有限几个数本身不能证明只有一种规律。","reflection":"第六座塔的高度，和第六次增加，是同一件事吗？","batch":"B05"},"equality":{"topicId":"mt_oIzycTBeE4","title":"两边一样多才放平","formal":"等号的关系意义","summary":"等号表示两边的值相同，不是“下一步写答案”。6 = 6 成立，4 + 1 与 5 + 2 的值不同。换一种写法仍可以保持平衡。","reflection":"5 = 2 + 3 为什么也是正确的？","batch":"B05"},"unknown":{"topicId":"mt_3JgrHY221M","title":"空盒里要放多少","formal":"加减法中的未知数","summary":"方框表示一个暂时不知道的数。找它时让等号两边相等，再把找到的数放回去核对；空盒可在不同位置。","reflection":"5 = □ − 3 时，空盒为什么不能填 2？","batch":"B05"},"represent":{"topicId":"mt_EBYGhd8X3x","title":"把故事搭成一张图","formal":"具体情境、图与算式的连接","summary":"先辨认整体和部分，再画图、写算式。相同关系可写加法或减法；数字的意义来自故事，不只是能算对的符号。","reflection":"总共 10 个、已知 6 个，为什么不能把 6 和 10 当作两个部分相加？","batch":"B05"},"explain":{"topicId":"mt_kJ5wYzO8qC","title":"让别人看见你的办法","formal":"解释数学推理","summary":"把方法的关键关系展示出来：拆出的各部分要合回原数，换一种表示可以交叉检查。找到具体哪一步出错，比只说答案不对更有用。","reflection":"8 + 5 为什么可以变成 8 + 2 + 3，而不能是 8 + 2 + 5？","batch":"B05"},"justify":{"topicId":"mt_pyMD_SIiYO","title":"试过几次，能说总是吗","formal":"说明理由、一般论证与反例","summary":"十个一可以换成一个十，进位时总量不变。任意偶数都能分成完整的对，两组完整的对合起来仍无剩余，这解释了偶数加偶数为偶数。几个例子不是对全部情况的证明；一个反例就能推翻“所有数相加都为偶数”。","reflection":"你的理由为什么能适用于没试过的偶数？","batch":"B05"},"countonce":{"topicId":"mt_WcfaSfVT33","title":"数过的，别数第二次","formal":"一一对应计数","summary":"数一个物品，只给它一个序号；所有物品都要数到。把数过的分开，能避免漏数和重复。","reflection":"怎样发现同一个物品被数了两次？","batch":"B06"},"lastcount":{"topicId":"mt_dmNvjroCPT","title":"挪个位置，还这么多吗","formal":"基数与数量守恒","summary":"从一开始，每件物品恰好数一次，最后的数才表示总数。只换排列或计数次序，没有添取物品，总数不变。","reflection":"最后说出的数为什么有时不能直接当总数？","batch":"B06"},"counttwenty":{"topicId":"mt_yqAL6O5i_v","title":"从一堆里，正好取出这些","formal":"二十以内的实物计数","summary":"数清一堆与按要求取出一部分都要一一对应。目标数也告诉我们何时停下。改变摆法不改变总量。","reflection":"散着摆时，你怎样防止漏数？","batch":"B06"},"paircounts":{"topicId":"mt__h7hvT4tEb","title":"排得长，就一定多吗","formal":"用匹配和计数比较数量","summary":"一对一配完后，多出的一方数量更多；两边无剩余则相等。拉大间距没有增加物品。比较的是数量，不是排列的长度或物品的大小。","reflection":"配对和数两边，为什么能得到相同结论？","batch":"B06"},"nextone":{"topicId":"mt_sYpKWbq5ra","title":"只加一个，要重新数吗","formal":"相邻自然数与多一少一","summary":"增加一个就到后一个数，拿走一个就到前一个数。这个关系把物品数量与数轴上一格联系起来。","reflection":"为什么知道原来七个，就能想到再加一个是八个？","batch":"B06"},"manyfaces":{"topicId":"mt_pAcaehday5","title":"这些画法，能说同一个数吗","formal":"数的多种表示","summary":"物品、点图、数字和数轴位置可以表示同一数量。数轴的零是起点，走过的单位间隔才是数量。","reflection":"怎样检查几个表示没有各说各的？","batch":"B06"},"quickfive":{"topicId":"mt_t9BICauBSI","title":"一眼里，看见了几个","formal":"五以内的快速识数","summary":"小数量可以作为一个整体认出。熟悉和不同的点阵都值得观察，也可用手指一次表示。短时显示只记录这次表现，不能知道你是否在心里逐个数。","reflection":"哪种摆法容易看出来？换一种摆法还认得吗？","batch":"B06"},"partswithin":{"topicId":"mt_BK5xwkrD5C","title":"先看几和几，再看一共","formal":"十以内的部分与整体","summary":"一个总量能看成几个部分。七可以看成五和二，八可以分成四和四或五和三；分法变化，总量保持。","reflection":"你能把八分成另一种不同的两部分吗？","batch":"B06"},"bundles":{"topicId":"mt_0ZDouU664X","title":"一大堆，怎样数得不乱","formal":"分组计数与单位化","summary":"把物品分成同样大的组，可以按组计数，再加上不满一组的剩余。每件物品只能属于一组，扎束和拆开都不能改变总数。","reflection":"八束十个和五个零散的，为什么不是十三个？","batch":"B06"},"countline":{"topicId":"mt_M5PPDJStGm","title":"不用从一开始，也能接下去","formal":"一百以内的顺数与倒数","summary":"相邻自然数相差一。能从不同起点接着数、跨过整十并倒着走，才不只是记住从一开始的一长串。口头数数可对照百数表练习，这里不自动评估发音和口述流利程度。","reflection":"从二十九到三十，哪个位置发生了变化？","batch":"B06"},"skipbasic":{"topicId":"mt_nvdpxAJTBG","title":"一双一双、一组一组数","formal":"按二、五、十跳数","summary":"每次增加相同数量的一组，数轴就走相同长度。跳数和重复加同一个数相对应。","reflection":"数五组两只袜子时，每一次跳跃表示什么？","batch":"B06"},"skipthree":{"topicId":"mt_aHAM29nidj","title":"三格一步，回来也一样吗","formal":"按三顺数与倒数","summary":"向前每次加三，向后每次减三。方向变化，步长保持；不必每次从零重新数。","reflection":"从三十倒着走，第一步为什么不是二十九？","batch":"B06"},"anytens":{"topicId":"mt_OkSJfrmFb_","title":"从七开始，也能十个十个走","formal":"从任意数按十计数","summary":"加十或减十改变十的数量，个位保持。跨过整百时可能同时改变百位，不能只改一个数字而忽略进退位。","reflection":"九十七加十时，为什么个位仍是七？","batch":"B06"},"withinthousand":{"topicId":"mt_M2v1A9OEuM","title":"走到整百边上，会怎样","formal":"一千以内的连续计数与跳数","summary":"可按一、五、十或一百计数；步长决定每次改变多少。跨整百、整千时，需保持数量变化一致。","reflection":"九百九十五之后每次加五，会走到哪里？","batch":"B06"},"skipfour":{"topicId":"mt_IzQvs7k_sE","title":"换大一点的步子","formal":"按四、八、五十、一百跳数","summary":"把每一组当作一个单位，按固定步长累积。四的两步与八的一步可以到同一位置，五十的两步组成一百。","reflection":"不同步长能落在同一个位置吗？","batch":"B06"},"skipbig":{"topicId":"mt_7rJM8eWUfw","title":"每次成组，规律还在吗","formal":"按六、七、九、二十五、一千跳数","summary":"每个数仍由前一个加固定步长得到。熟悉整组结构能帮助计数，但不会改变一组中实际有多少。","reflection":"四组二十五为什么能连到一百？","batch":"B06"},"powersteps":{"topicId":"mt_tAtMET4EIU","title":"改一步的大小，哪些位会动","formal":"按十的幂计数与进退位","summary":"按十、一百、一千、一万、十万改变数量。跨过某一数位的边界会发生进位或退位，相关高位也随之改变。","reflection":"四十九万二千加一万，为什么不只是把一个数字加一？","batch":"B06"},"write20":{"topicId":"mt_fR0UtsSREU","title":"把听到的数，摆出来写下来","formal":"二十以内数字的读写与数量对应","summary":"数字表示一个数量；零表示没有。十几由一个十和几个一组成。这里核对数值与构造，手写笔迹保存待看，不自动判定是否写得清楚。","reflection":"十七的两个数字分别告诉了什么？","batch":"B06"},"teenbuild":{"topicId":"mt_xmmgAzxe5j","title":"十个扎成一束，还剩几个","formal":"十几的十与一结构","summary":"十个一可以组成一个十。十四是一个十和四个一；十七能拆成十加七。扎束或拆开，总量不变。","reflection":"十三里的“一”为什么代表十个？","batch":"B06"},"numberwords":{"topicId":"mt_9IzhGUZ30z","title":"数字的名字，也能当标签","formal":"数词、数字与数量（中文适配）","summary":"十二、12 和十二个物品指向同一数量；写文字标签也要保持数量。这是原英文数词目标的中文改编，不代表完成英语拼读或拼写。","reflection":"“十二”与“二十”的标签能贴在同一堆上吗？","batch":"B06"},"digitcompare":{"topicId":"mt__YRJ23GuIK","title":"只写两个数字，怎样比","formal":"数字大小比较与关系符号","summary":"数字表示数量，数轴上较右的位置表示更大的数。小于号和大于号的开口朝较大数，相同数量用等号。","reflection":"把两个数交换左右，关系符号要怎样变？","batch":"B06"},"order20":{"topicId":"mt_dJOKkYMsCv","title":"把这些数字放回队伍","formal":"二十以内数的顺序与相邻数","summary":"从小到大排列看数量，零也有位置。前一个少一，后一个多一；二十格图与数轴能帮助检查顺序。","reflection":"十三前后各是谁？零应该放在哪里？","batch":"B06"},"write100":{"topicId":"mt_x8TshvbbQT","title":"听起来相近，写出来一样吗","formal":"一百以内数字的读写与位值","summary":"几十和几个一按十位、个位写；零需要占位。一百是一个百。这里以中文听读数值，核对结构与数字，笔迹清晰度不自动评分。","reflection":"四十、十四和四十一怎样用整十和零散的一表示？","batch":"B06"},"tenexchange":{"topicId":"mt_r0VXbfAmsH","title":"十颗装成一条，还是十颗吗","formal":"十个一与一个十","summary":"十个一换成一个十，数量没有增减；也能拆回来。条上的十格说明它并不是一个一。","reflection":"拆开一条，为什么不是增加了九颗？","batch":"B07"},"twoplaces":{"topicId":"mt_THl9GLxwoL","title":"同一个4，站哪里很重要","formal":"两位数的位值","summary":"47中的4表示四个十，即40；7表示七个一。数字的位置决定它所表示的单位。","reflection":"47和74用了同样的数字，数量为什么不同？","batch":"B07"},"decades":{"topicId":"mt_zfy1gOEewd","title":"只有整条，最后写什么","formal":"整十数与零占位","summary":"30是三个十和零个一。个位的零保留了位置，30不是3。","reflection":"50拿走一条后，个位为什么仍是零？","batch":"B07"},"rename":{"topicId":"mt_Bt-iORUzdO","title":"换个装法，一颗也没变","formal":"两位数的非标准分拆","summary":"34可以是三个十加四个一，也可以是两个十加十四个一。拆包只改变表示，不改变总量。","reflection":"只剩散颗时，还能认出原来的总数吗？","batch":"B07"},"shift10":{"topicId":"mt_kw7xmp68rU","title":"多一整条，哪些不用重数","formal":"多十、少十与位值","summary":"添一条十就是加十，拿走一条就是减十。未跨百时，个位保持，十位相应变化；跨百还需换装。","reflection":"多十和多一，物品上分别改变了什么？","batch":"B07"},"twoproblems":{"topicId":"mt_kJGCjnuelW","title":"用整包装法，解决一件事","formal":"用位值与数的组成解决问题","summary":"可以先把整十与零散的一分开，再添取、合并；倒推原来的数量也能用相反的操作。","reflection":"知道最后45并且添过10，怎样找回原来多少？","batch":"B07"},"compare100":{"topicId":"mt_U0waNfD8PB","title":"先看哪一堆，能更快比","formal":"两位数的比较与排序","summary":"先比较整十；十相同才比较一。相同的数量用等号，关系符号的开口朝较大数。","reflection":"个位大，整个数就一定大吗？","batch":"B07"},"faces100":{"topicId":"mt_9L3NQqgqRd","title":"一堆、几条和一个位置","formal":"一百以内数的表示与估计","summary":"同一数量可以用方块、简图、百数表和数轴表示。估计是先判断大约多少，再用准确计数核对。","reflection":"估计和准确数清，分别在什么时候有用？","batch":"B07"},"parity":{"topicId":"mt_hniI4E-OCE","title":"两两做伴，会剩一个吗","formal":"奇数、偶数与相等加数","summary":"每件都能两两配对、没有剩余的是偶数；剩一个的是奇数。偶数也能分成相等的两组；零也没有剩余。","reflection":"为什么加一个会改变有没有剩余？","batch":"B07"},"words100":{"topicId":"mt_76SPWvdI7r","title":"给一大包写个中文标签","formal":"百以内的数词与数量（中文适配）","summary":"五十七、57、五个十和七个一可以指同一数量。这里练中文数词，原英文拼写目标没有被评估。","reflection":"五十七为什么不能写成507？","batch":"B07"},"read120":{"topicId":"mt_XV0B4kWwqL","title":"过了一百，还能接着数","formal":"一百二十以内的读写与计数","summary":"99后面是100，再到101；108保留空十位。按位写数字，不能把一百和八拼成1008。口述流利度不自动评估。","reflection":"108中间的零在替谁留位置？","batch":"B07"},"faces120":{"topicId":"mt_QguIGVMB1o","title":"一百之外，也放得进去","formal":"一百二十以内的多种表示","summary":"112可以用十一条十和两个一，也能换成一百、一十和二个一。数表与数轴仍保持每一步增加一。","reflection":"十一条十与一个百一个十有什么联系？","batch":"B07"},"hundredexchange":{"topicId":"mt_8gy7uxRlF6","title":"十条并在一起，成为一整板","formal":"十个十与一个百","summary":"一百是十个十，也是100个一。百格板的一排是十，一共十排；合成和拆开都守恒。","reflection":"一板看起来只有一块，为什么表示100？","batch":"B07"},"threeplaces":{"topicId":"mt_aPBzD28_mT","title":"三格位置，空格也算数","formal":"三位数的位值与展开","summary":"362由300、60、2组成；706里没有零散的十，但必须保留十位的零。","reflection":"706写成76，会改变哪部分的数量？","batch":"B07"},"hundreds":{"topicId":"mt_R2ccrI-nKD","title":"整板往上加，两个零去哪","formal":"整百数与数轴位置","summary":"300是三个百，十位和个位都是零；这不妨碍把300全换成30个十。数轴上每一百的间距相同。","reflection":"300的十位是0，为什么还可以换成30条十？","batch":"B07"},"shift100":{"topicId":"mt_izien3ZX51","title":"加一条、加一板，哪里会动","formal":"三位数的多十少十、多百少百","summary":"加减十或百先改变相应单位的数量。遇到十条或没有可拿的条，要合成或拆开百；因此可能有多个数字一起改变。","reflection":"300拿走10，为什么百位和十位都变了？","batch":"B07"},"compare1000":{"topicId":"mt_AQcVRBddko","title":"把空位对齐，再比较","formal":"一千以内的比较与排序","summary":"从最高位开始比，相同才往右。305与350的百相同，由十位决定大小；99还不到一个百。","reflection":"为什么608比680小，却比86大？","batch":"B07"},"problems1000":{"topicId":"mt_98c2qwEF7Q","title":"有多少整包，怎样付刚好","formal":"位值的实际应用与重新单位化","summary":"同一总量可按百、十、一重新分组。问整共有多少个十，和问十位数字，是不同的问题。","reflection":"236能装多少个十个一包，剩几个？","batch":"B07"},"words1000":{"topicId":"mt_VFsuftfvYM","title":"给三位数翻译三种写法","formal":"一千以内数的读写和展开（中文适配）","summary":"数字、中文数名与展开式可以互相对应。内部或末尾的零要按位保留；展开十位要写它的值。","reflection":"637里，3为什么要展开成30？","batch":"B07"},"faces1000":{"topicId":"mt_F_zEAJ8VIo","title":"把大数放在合适的位置","formal":"一千以内的表示与估计","summary":"数轴的相对位置反映数量；507的十位为空；3百14十2一与442等量。表示变化时用交换检查。","reflection":"点在0到1000的四分之三附近，大约表示多少？","batch":"B07"},"screen1000":{"topicId":"mt_HczwO1sr-y","title":"十个百，能合成什么","formal":"一千以内的屏幕构造与排序","summary":"十个百可以合成一个千，也能拆回。屏幕构造、数位和数轴位置需表达同一数量；实物操作仍需实际尝试。","reflection":"千还能拆成多少条十？先想想怎样交换。","batch":"B07"},"fourplaces":{"topicId":"mt_jY7uf0Cb7o","title":"让每个数字站对位置","formal":"四位数的位值与分拆","summary":"7345中的7表示7000，不是7。把各位的值相加，可以重新得到原数；空位用0保留。","reflection":"3452中的4，为什么要记成400？","batch":"B08"},"fourfaces":{"topicId":"mt_lC_Q5mSL_I","title":"同一个大数，换个样子","formal":"一万以内数的表示与估计","summary":"数位筹码、展开式和数轴可以表示同一数量。筹码标明单位，大小不是实物体积的比例。","reflection":"同是一个筹码，标1与标1000有什么区别？","batch":"B08"},"thousandstep":{"topicId":"mt_9XVFje6Tyr","title":"一大包一大包地添和拿","formal":"多一千、少一千","summary":"加减1000通常改变千位；跨过整万时需要换组，万位和千位都会改变。不能说永远只变一位。","reflection":"9500再添1000，哪几个位置一起变了？","batch":"B08"},"bigcompare":{"topicId":"mt_MHaiUd2FLA","title":"谁多谁少，先比大单位","formal":"较大整数的比较与排序","summary":"对齐数位，从最高位开始比较，相同才往右看。数轴上较大的数在右边。","reflection":"4009和4090，个位大的一定更大吗？","batch":"B08"},"roundwhole":{"topicId":"mt_NLSfvB9vUl","title":"报个大概，要报到哪一站","formal":"按十、百、千取近似值","summary":"先确定间隔，再看原数离哪一站更近。这里对非负数约定：正好一半时取较大的一站。每次都从原数判断。","reflection":"同一个4367，为什么可以报成4370、4400或4000？","batch":"B08"},"placeproblems":{"topicId":"mt__sMrmOv3bx","title":"大概够不够，准确差多少","formal":"用位值解决大数问题","summary":"比较、排序和取近似值各有用途。预报大概人数可取整，计算两处准确差距仍需原数。这里的人数与距离是练习数据。","reflection":"准备接待时，哪些地方可以估，哪些必须精确？","batch":"B08"},"tenpattern":{"topicId":"mt_QqG6IdmTSE","title":"同一个数字，向左住一格","formal":"相邻位值的十倍关系","summary":"十进制里，同一数字左移一位表示原来的10倍。3000是300的10倍，700是70的10倍。","reflection":"两个5的样子一样，为什么值能差十倍？","batch":"B08"},"sixdigits":{"topicId":"mt_JwP9QFv6gQ","title":"给很长的数字分好住址","formal":"六位数的读写、展开与比较","summary":"按位对齐保留0；中文按万分组读。这里的中文读写是本地适配，不评估原英文拼写或朗读流利度。","reflection":"403072为什么不能把中间的0都去掉？","batch":"B08"},"bigproblems":{"topicId":"mt_xMt1TLTs--","title":"有限的数字，摆出最大的数","formal":"大数的构造、估算与应用","summary":"位数相同，先让最高位尽可能大。估算与准确比较用途不同；这里的场馆与城市数据都是设定情境。","reflection":"数字加起来一样多，放在哪儿会让整个数更大？","batch":"B08"},"millionwords":{"topicId":"mt_Gag_h98jWP","title":"一长串数字，也能读明白","formal":"千万以内整数的读写与位值","summary":"中文读法按万分组，空位不能随意删除。7045200里的7表示7000000；英文的千、百万分组另属语言适配。","reflection":"7045200的7和745200的7，值相同吗？","batch":"B08"},"roundlarge":{"topicId":"mt_5NwqN6pf_A","title":"大数字，也有最近的一站","formal":"较大整数的四舍五入","summary":"根据指定单位找相邻两站，用原数与中点比较。950500到最近十万为1000000，十进位会跨过原来的最高位。","reflection":"950000和950500，为什么都能报成一百万？","batch":"B08"},"tenmillion":{"topicId":"mt_XNmGwNggdU","title":"数到千万，也走向零以下","formal":"千万以内的估计与负数排序","summary":"大数可按需要估到百万；负数在零左边，越向左越小。模拟深度用负数表示相对水面的高度，不是真实海沟测量。","reflection":"-8000比-7000更深，为什么数值反而更小？","batch":"B08"},"decimalscale":{"topicId":"mt_EDgw64OmfA","title":"跨过那一点，规律还在吗","formal":"整数与小数位值的十倍关系","summary":"小数点固定，各位数字左移一位是乘10，右移一位是除10。0.04是0.4的十分之一；6000是0.006的一百万倍。","reflection":"向右移一格，为什么不是简单地删一个0？","batch":"B08"},"decimalplaces":{"topicId":"mt_lNGpnILM5C","title":"一份不够大，再分成小份","formal":"小数数位与单位分数","summary":"十分之一、百分之一、千分之一依次变小，每向右一位是前一位的十分之一。4.073里空着的是十分位。","reflection":"0.07与0.007，哪份更大？怎样用分份解释？","batch":"B08"},"decimalwords":{"topicId":"mt_Ac7oMWhyPw","title":"小数的名字，也要带单位","formal":"小数读写、展开与比较","summary":"347.392的每位都有单位；5又千分之62写成5.062。比较小数可补末尾0对齐位置，0.38=0.380，不按数字个数比大小。","reflection":"0.372写得更长，为什么还比0.38小？","batch":"B08"},"rounddecimal":{"topicId":"mt_Fl7b8q9pI1","title":"离哪一个整站更近","formal":"一位小数取最近整数","summary":"把原数放在相邻整数之间，用距离决定靠哪一边。这里6.5正好一半，按约定取7。","reflection":"3.7与3.2为什么会去不同的整站？","batch":"B08"},"roundtenths":{"topicId":"mt_Ii1hV4V5ql","title":"留一位，还是留到整数","formal":"小数按精度取近似值","summary":"3.47取整数是3，取一位小数是3.5；12.95取一位小数写13.0，末尾0表达保留到十分位。不要连续逐位取整。","reflection":"估算4.83+2.17，结果可能正好等于准确和吗？","batch":"B08"},"roundprecise":{"topicId":"mt__casygEB85","title":"先想用途，再定留多细","formal":"按指定单位取近似值与估算","summary":"3.4567保留两位小数为3.46；7654321按十万取近似值为7700000。估算乘法可先分别取近似值。","reflection":"4.83×2.17估为10，能当作精确答案吗？","batch":"B08"},"accuracy":{"topicId":"mt_U9sme87C32","title":"留下几位，留下哪些位","formal":"小数位数、有效数字与精度","summary":"小数位从点后开始数；有效数字从第一个非零数字开始。0.004982取两位小数为0.00，取两位有效数字为0.0050；末尾0记录精度。","reflection":"0.00与0.0050为什么都能从同一个数得到？","batch":"B08"},"estbounds":{"topicId":"mt_VVn1IXjkzn","title":"只知道大概，还能知道什么","formal":"估算与误差区间","summary":"非负数按四舍五入报到某单位，原数位于报告值减半个单位到加半个单位之间：下端包括，上端不包括。它是一个范围，不是唯一原数。","reflection":"报12米，原长可能刚好12.5米吗？试试边界。","batch":"B08"},"powerpattern":{"topicId":"mt_HLUqHJ9Y7n","title":"十倍，再十倍，会发生什么","formal":"10的幂与位值移动","summary":"10⁴表示四个10相乘；乘10²就是连续左移两位，3.4×10²=340。指数数的是因子10的个数，不能理解为给任何数添几个0。","reflection":"为什么3.4乘100不是3.400？","batch":"B08"},"standardform":{"topicId":"mt_bO-njVOige","title":"很大很小，都装进短写法","formal":"科学记数法","summary":"正数可写成A×10ⁿ，其中1≤A<10。正指数放大，负指数缩小；负指数不表示这个数是负数。比较正的规范写法，可先比指数。","reflection":"7.2×10⁻⁴为什么仍大于0？","batch":"B08"},"roman100":{"topicId":"mt_MewIRdzpzz","title":"换一套符号，还能记数量吗","formal":"罗马数字与非位值记数","summary":"I、V、X、L、C分别表示1、5、10、50、100。XLIV=40+4=44；常用规范中IV表示4。符号没有十进制的位置升值，也没有单独的零符号。","reflection":"XX的两个X为什么都是10？","batch":"B08"},"romanyears":{"topicId":"mt_To9HdLy8vq","title":"用旧符号写一个年份","formal":"较大罗马数字的组合","summary":"D是500、M是1000；MCMXCIX=1000+900+90+9=1999，2024写MMXXIV。源标题写到1000，实际目标包含这两个更大的年份。钟面上的IIII是另一传统写法。","reflection":"2024里没有的百位、十位，罗马数字需要用零占住吗？","batch":"B08"},"linejumps":{"topicId":"mt_19j_5AuuQI","title":"把一笔计算画成一段路","formal":"数轴上的加减与等距刻度","summary":"数轴的间隔表示数量。38加27可以先走20再走7；52减24向左走。箭头长度表示改变了多少，终点表示结果。屏幕按比例画图，不等于已会徒手作图。","reflection":"38到58这一段，为什么写20而不是58？","batch":"B09"},"toolchoice":{"topicId":"mt_zMEvtigoM3","title":"这件事，用哪件工具顺手","formal":"按目的选择数学工具","summary":"数轴适合看跳了多远，百数表能按十和一移动，小方块便于看少量物品怎样合起来。量实际长短要用有单位的尺；长物体可换长尺或分段量。没有永远最好的工具。","reflection":"短丝带和高门，换工具后能少做哪些重复动作？","batch":"B09"},"negativefirst":{"topicId":"mt_vXRzMbiPff","title":"走到零，还能往前走吗","formal":"负数、顺序与零的参照","summary":"从5倒数会经过0，再到−1、−2。负数在零左侧，−5比−2小。温度的0是标尺参照，不是“没有温度”。","reflection":"−5里的5更大，为什么−5反而比−2小？","batch":"B09"},"negativecontext":{"topicId":"mt_1KkvzwYxbR","title":"从零下走到零上","formal":"情境中的负数与跨零间隔","summary":"从−4℃升高7度，可以先走4度到0，再走3度到3℃。地面、海平面或温度标尺的零各有自己的含义。画面是模拟情境。","reflection":"从−4到3，为什么不是走了1步？","batch":"B09"},"signedwalk":{"topicId":"mt_9QzSnn8m80","title":"方向也能被拿走吗","formal":"有符号数的加减","summary":"加上负数朝左；减去一个变化，要反向撤销它。1−(−3)撤销向左3，相当于向右3。减号是操作，括号里的负号说明方向。","reflection":"1−(−3)里两个减号，分别告诉你什么？","batch":"B09"},"distancezero":{"topicId":"mt_RWUY7_IXvw","title":"站在哪里，和离家多远","formal":"绝对值与零点距离","summary":"绝对值是数轴上离0的距离，总不小于0。−5和5的位置不同，距离都是5。−8比−3小，却离0更远；位置大小与距离大小不能混为一谈。","reflection":"欠8元和欠3元，谁的余额更小，谁欠得更多？","batch":"B09"},"allowedrange":{"topicId":"mt_i2F1nWxJjv","title":"可以选的数，是一个还是一片","formal":"不等式与解集","summary":"至少12表示x≥12：包括12，并且所有更大的数都可以。空心点不含端点，实心点包含端点。同加减或同除正数保持大小关系；3x+1<10可化成x<3。","reflection":"x<3为什么不只是“答案等于2”？","batch":"B09"},"powerblocks":{"topicId":"mt_hCVPYlF-7Y","title":"每条边一样长，会有多少块","formal":"平方、立方、整数幂与方根","summary":"平方是两个相同因子相乘，立方是三个；方根反过来找边长。10个2相乘是2¹⁰。乘方先于加法，3+2²=7。√2是精确数，1.414只是近似值，二者不能写等号。","reflection":"64块拼成正方体，每条边几块？为什么不是64÷3？","batch":"B09"},"numberworld":{"topicId":"mt_b4lbTOJYwI","title":"两点之间，还能放进新点吗","formal":"有理数、无理数与数的稠密性","summary":"能写成整数之比、且分母非0的数是有理数，小数会终止或循环。√2、π是无理数，√9=3却是有理数。两个不同实数之间总能取中点，再取中点，因此有无穷多个数。有限次缩放只演示，不能代替这个理由。","reflection":"0.333…很长，为什么还是分数？把两点放得再近，会没有中点吗？","batch":"B09"},"jointhings":{"topicId":"mt_OvyoRo47K-","title":"两小堆，变成一大堆","formal":"加法：合并与增加","summary":"两堆原来分开放，也可以看成一个整体；后来又来一些，也会形成新的整体。加法记录这两部分合起来有多少。","reflection":"“原来有两堆”和“又来了一些”，哪里相同，哪里不同？","batch":"B10"},"takethings":{"topicId":"mt_zuKAX6lcYR","title":"拿走以后，还剩哪些","formal":"减法：取走、缺少的部分与差","summary":"拿走一部分，剩下的是另一部分；两排一一配对后，多出的部分也是差。减法可以表示取走，也可以找缺少多少或相差多少。","reflection":"7颗与4颗比多少，为什么不必真的丢掉任何一颗？","batch":"B10"},"showactions":{"topicId":"mt_PgsHGYJMH-","title":"同一件事，换一种画法","formal":"加减法的多种表征","summary":"小圆片、点图、手指图和算式可以表示同一个数量关系。换画法要保留原来的部分与整体。屏幕手指图不能代替真实手指动作。","reflection":"换成点图后，原来的3和2分别在哪里？","batch":"B10"},"smallstories":{"topicId":"mt_yJmvUCCym7","title":"把故事摆出来","formal":"十以内加减应用与未知位置","summary":"先找故事里的原有数量、变化和结果，再用物品表示。问题可能问结果，也可能问最初有多少或后来来了多少，不能只凭某个词选择运算。","reflection":"“又来了”就一定要把题里两个数相加吗？","batch":"B10"},"screenstories":{"topicId":"mt_Y6_cq3UMyy","title":"让小圆片演一遍","formal":"用屏幕计数物表示数量故事","summary":"把数量摆出来，再让圆片到来或离开。换成点图，数量关系不变。真实物品与屏幕圆片的对应还可以拿实物试一试；这里不会自动判定实物操作。","reflection":"换了画法，哪一些东西变了，哪一些没有变？","batch":"B10"},"screenadd":{"topicId":"mt_biGHAbkoV2","title":"搬一搬，让十先站出来","formal":"屏幕十格框中的拆分与跨十","summary":"8可以分成5和3，也可以分成6和2。8+5先搬2个填满十，剩下3个；15−7先拿走5到十，再拿走2。搬动的是同一批圆片。","reflection":"凑十时搬走的2个，为什么不能再算一遍？","batch":"B10"},"signsfirst":{"topicId":"mt_8RmpkDxT9L","title":"把刚才的动作写下来","formal":"加号、减号与等号","summary":"＋记录合起来，−记录取走或比较差。＝表示两边数量相同，所以5=3+2也成立，4+1=3+2也成立。读出来、手写清楚还需要实际练习。","reflection":"等号后面一定只能写一个答案吗？","batch":"B10"},"basicadd":{"topicId":"mt_mr_Vk7FGzK","title":"多一点，少一点，不变呢","formal":"二十以内加减与零的作用","summary":"加的是几个一，就增加几个一；减去几个一，就减少几个一。加0或减0都没有圆片到来或离开，数量保持原样。","reflection":"做了一个运算，数量一定会变吗？","batch":"B10"},"earlyunknown":{"topicId":"mt_VAWV_l7J0D","title":"结果知道，开头藏在哪里","formal":"二十以内应用与缺数问题","summary":"7=□−9是在问：原来有多少，拿走9后还剩7。可以把9和7重新合起来找到16，再实际拿走9检查。未知数可以在开头、变化处或结果处。","reflection":"看到减号时，为什么有时要用加法找原来的数量？","batch":"B10"},"splitpairs":{"topicId":"mt_7XcCG43ZZW","title":"一堆东西，有几种分法","formal":"数的分解与部分—整体","summary":"整体不变，两部分可以一边多一颗、另一边少一颗。5的不同配对有0和5、1和4、2和3；交换左右还是同一对。零也是一种部分。","reflection":"怎样有顺序地找，才不漏掉一种分法？","batch":"B10"},"partnersten":{"topicId":"mt_e8CZ7E5qW7","title":"还缺几个，刚好装满","formal":"凑十的数对","summary":"十格里已有7个，缺的3个与7合成10；已有6个，就缺4个。已知一部分和整体，可以找另一部分。","reflection":"“还缺几个”和“一共有几个”，问的是同一件事吗？","batch":"B10"},"factsfive":{"topicId":"mt_ghF3Vv6taM","title":"五以内，想不起来就拆开","formal":"五以内的加减事实","summary":"2+3=5、5−2=3和5−3=2来自同一个整体。想不起来可以重新摆一摆。做完这里的少量活动，不代表已经能熟练回忆全部算式。","reflection":"忘记5−2时，怎样用两部分帮自己找回来？","batch":"B10"},"bonds20":{"topicId":"mt_s2mfRBoTal","title":"三个数，能写几句话","formal":"二十以内的加减事实族","summary":"8、5、13连着四句话：两种顺序的加法，以及整体减去其中一部分的两种减法。不同整体的配对不能混在一起。","reflection":"13−5为什么能从8+5里直接找出来？","batch":"B10"},"bridge20":{"topicId":"mt_m1W6nTQJ2b","title":"经过十，再往下走","formal":"凑十与破十策略","summary":"8+6把6拆成2和4，先到10，再加4。13−4把4拆成3和1，两次都要拿走：先到10，再到9。","reflection":"减到十以后，剩下的那部分是加回来还是继续减？","batch":"B10"},"factsten":{"topicId":"mt__we2TDqnJx","title":"十以内，找回熟悉的组合","formal":"十以内加减事实与策略","summary":"已知的数对可以帮助重建忘记的算式；加法与相关减法一起练。这里不计时，做完也不等于已经熟练掌握所有十以内算式。","reflection":"7−3和4+3，怎样互相帮忙？","batch":"B10"},"factstwenty":{"topicId":"mt__t4afSyZRm","title":"跨过十，也有熟悉的伙伴","formal":"二十以内加减事实与策略","summary":"15−8可以借助8+7=15，也可以先减5到10再减3。熟练需要不同日子的实际表现；本活动不判定三秒回忆或全范围熟练。","reflection":"知道一个加法，能少记哪两个减法？","batch":"B10"},"countsteps":{"topicId":"mt_PpWSHA-0kv","title":"从已有的数，接着走","formal":"接着数与倒着数","summary":"算8+3，从8出发，三步依次是9、10、11。起点8不算第一步。减法向回走；加法可以从较大的一部分接着数。","reflection":"为什么从8走三步，不是8、9、10？","batch":"B10"},"swapadd":{"topicId":"mt_QCgbiVrwnp","title":"交换两堆，总数会变吗","formal":"加法交换律及其边界","summary":"3+8和8+3只是交换同一批东西的位置，整体不变。5−3与3−5却不同：3个实物拿不出5个。实物取走模型到这里就不够用了，负数在另一条路线。","reflection":"为什么加法换顺序可以，减法不能照搬？","batch":"B10"},"tripleadd":{"topicId":"mt_Zx1xZM-RbX","title":"三堆里，先合哪两堆","formal":"三个数相加的便利策略","summary":"先找能凑十的一对，或两个相同的数，再带上第三堆。其他配对也可能算对；少算或重复算第三堆会改变总数。","reflection":"先合7与3以后，原来的5去哪里了？","batch":"B10"},"regroupadd":{"topicId":"mt_T76hKqXf0z","title":"先合谁，最后会一样吗","formal":"加法结合律及其边界","summary":"同样三个部分，先合不同的两部分，总数不变。改变相邻两部分的组合是结合；跨位置选一对还用了换顺序。减法不能照搬：(10−3)−2=5，10−(3−2)=9。","reflection":"换的是位置，还是先算哪一组？","batch":"B10"},"scaleadd":{"topicId":"mt_3e_PQxwC12","title":"一颗变成一捆，关系还在吗","formal":"利用数对推导整十与进十加法","summary":"6个一加4个一是10，6个十加4个十是100。35+5是增加5个一，可以把10个一换成1个十；35+50是增加5个十，结果85。","reflection":"35+5和35+50，看起来都多了5，为什么结果不同？","batch":"B10"},"undoadd":{"topicId":"mt_ehGS_uVSJv","title":"把变化倒着做回来","formal":"加减互逆与缺数检验","summary":"15+7=22，取走同样的7就回到15。□+9=14可以用14−9找缺的5，再用5+9检查。加减互逆围绕同一个整体和两个部分。","reflection":"再算一次加法，和用减法倒着检查，有什么不同？","batch":"B10"},"onesbridge":{"topicId":"mt_AKAtWEwpcj","title":"多几颗，整捆也会变吗","formal":"两位数与一位数的加减","summary":"36+7可以先添4到40，再添3到43。52−4可以先退到50，再退2。跨过整十时，十位也会变化。","reflection":"43+5与36+7，为什么只有后者需要换出一整捆？","batch":"B11"},"tensmove":{"topicId":"mt_I5j1ZWo2cn","title":"这次搬的是整捆","formal":"两位数与整十数加减","summary":"45+30添的是3个十，个位的5不变；45+3添的是3个一。跨过100时，百位也要变化，不能总说只有十位变。","reflection":"加30与加3，分别改动哪一格？","batch":"B11"},"decadetake":{"topicId":"mt_HJTuIGHvcR","title":"拿走三捆，还是三颗","formal":"整十数相减与单位化","summary":"70−30是7个十拿走3个十，剩4个十，也就是40。70−3却要拆开一捆，再拿3个一。","reflection":"为什么70−30的结果不是4？","batch":"B11"},"twodigitpair":{"topicId":"mt_UQnAFPs83F","title":"两堆都带着整捆","formal":"两个两位数的加减","summary":"34+27先把相同单位合起来，11个一换成1个十和1个一。63−28要把1个十拆成10个一，再取走。","reflection":"拆开一捆时，数量是变少了，还是换了一种装法？","batch":"B11"},"addhundred":{"topicId":"mt_glPPG-kTQY","title":"找个整十，歇一下","formal":"百以内加法的位值策略","summary":"46+7可以先到50，再走3；38+40把4个十放进十位，个位的8保留。写下的每段变化要合成原来的增加量。","reflection":"先到整十这一步，为什么不能把剩下的忘掉？","batch":"B11"},"flexhundred":{"topicId":"mt_cChv2j_-Da","title":"同一道题，换条路走","formal":"百以内加减的灵活策略","summary":"位值拆分、先多加再退回、从小数走到大数，都能帮助计算。71−68可以看68到71有多远。方法合适与否要看这些数。","reflection":"71−68与83−25，你愿意分别怎么走？","batch":"B11"},"oneslarge":{"topicId":"mt_oDU_8zMZjp","title":"小小一颗，也能越过百","formal":"三位数与一位数的加减","summary":"加减几个一从个位开始；345+3不跨十，345+7会跨十，398+7还会跨百。高位保持不变是有条件的。","reflection":"398加7时，为什么百位也动了？","batch":"B11"},"tenslarge":{"topicId":"mt_aHQ9kNt3is","title":"整捆走远，也会跨百","formal":"三位数与整十数加减","summary":"加减整十数时，个位不变。十位满十要换成一个百；十位不够时，也可把一个百拆成十个十。","reflection":"372+40和345+40，哪个要换出一个百？","batch":"B11"},"hundredsmove":{"topicId":"mt_xPqczp7zPX","title":"整板搬动，零头留下","formal":"三位数与整百数加减","summary":"345+200是3个百再添2个百，45不动。762−400拿走4个百，留下362。本组不跨千。","reflection":"同样写一个2，加200与加20，搬的是同一种东西吗？","batch":"B11"},"showwhy":{"topicId":"mt_zxST3MarI9","title":"这条近路，凭什么成立","formal":"用位值与运算性质解释策略","summary":"拆分后每个部分仍在，所以能重新合成原来的总量。加99改成加100，多加了1，就要退回1。写步骤与说清理由是两件事。","reflection":"如果有人加100后又加1，你怎样指出多出的那部分？","batch":"B11"},"fourparts":{"topicId":"mt_TiQbi027PE","title":"四堆东西，先找谁结伴","formal":"多个加数的重排与组合","summary":"可以先把凑成整十的两堆合起来，也可以先合其他两堆；每堆只用一次，整体才不变。没有顺手的配对时，还能按单位拆分。","reflection":"先把两堆合并后，怎样确保另外两堆没漏掉？","batch":"B11"},"buildthousand":{"topicId":"mt_ewmuMMPAzP","title":"十捆再换一板","formal":"千以内加减与连续换单位","summary":"十个一换一个十，十个十换一个百，反过来也一样。402−137的十位空着，要先拆一个百，再拆一个十。","reflection":"中间空着一格时，从哪里换来需要的小单位？","batch":"B11"},"columnthree":{"topicId":"mt_SrrsLiJkr3","title":"把搬动缩成一张记录","formal":"三位数竖式加减与检验","summary":"竖式把相同单位上下对齐，把每次换单位压缩成记录。进位不是凭空添1，退位也不是让数量消失。先估一估，再用反方向检查。","reflection":"竖式上记下的1，在这一格到底值多少？","batch":"B11"},"flexthousand":{"topicId":"mt_HFRYjTb-Z5","title":"大一点，也能选近路","formal":"千以内加减的策略选择","summary":"300与298很近，可以数它们之间的距离；525+199可以先加200再退1。一般数也可用位值表或竖式。这里记录做法，不判定速度熟练。","reflection":"哪些数适合直接走几步，哪些值得写下来？","batch":"B11"},"columnfour":{"topicId":"mt_mpS-JK_p_m","title":"空格连续出现，怎么拆","formal":"四位数竖式与跨零换单位","summary":"4002里百位和十位都空着，可以从千位一路拆下来。数字位数不一样时，相同单位仍要对齐。做完可用相反运算检查。","reflection":"4002拆成3个千、9个百、9个十和12个一，为什么总量没变？","batch":"B11"},"columnlarge":{"topicId":"mt_Yw1_4Nfsql","title":"位置变多，规则没换","formal":"大整数竖式与多次进退位","summary":"大数仍然遵守十个小单位换一个大单位。三个数相加时，一格可能有24个，需换出2个更大的单位，不能总只进1。","reflection":"一格里有24个，与一格里有14个，向左送出的数量有什么不同？","batch":"B11"},"decimalsum":{"topicId":"mt_JH_6RpNWjr","title":"小数点两边，也能换整","formal":"小数加减与位值对齐","summary":"十个百分之一换一个十分之一，十个十分之一换一个一。3.4与3.40一样多；相同单位要对齐，小数点是定位标记。","reflection":"3.4与2.78相加，4应该和7对齐，还是和8对齐？为什么？","batch":"B11"},"storymoney":{"topicId":"mt_wzAZ8qFDc4","title":"故事还没结束，别停下","formal":"加减情境建模与中间结果","summary":"先看数量怎样变化，再选择加或减。花掉以后又得到，要留下中间结果并继续。看到“多”也不一定相加，要看问的是谁。","reflection":"32枚比小林多8枚，为什么找小林有多少时要减？","batch":"B11"},"storylarger":{"topicId":"mt_-F_Lv_apzH","title":"离目标还差几步","formal":"大数多步加减问题","summary":"把故事分成可检查的变化，每一步留下数量和单位。已收集多少与距离目标还差多少，是不同的问题。方法可以每一步重新选择。","reflection":"已经做出的中间结果，怎样帮助你检查有没有漏掉最后的问题？","batch":"B11"},"storymillion":{"topicId":"mt_M1tnXqmYbn","title":"数很大，故事仍要讲完","formal":"百万数量与小数的多步问题","summary":"大的数量和小数都要跟住每一次变化。估计能帮助发现少一位、多一位或小数点错位，但不能证明精确答案正确。","reflection":"如果算出来比估计少十倍，你先检查什么？","batch":"B11"},"mentalbig":{"topicId":"mt_MWXPiaTnEu","title":"把熟悉的关系放大","formal":"大数加减的派生事实与策略","summary":"45个千加8个千是53个千。10000−3200也可以从3200走到10000，答案是走过的总距离。近似相同的两个数可以借助已知的双倍。","reflection":"走到10000时，答案是10000，还是刚才走了多远？","batch":"B11"},"checkrough":{"topicId":"mt_QaYfeVL-0C","title":"先看大概，再倒着验","formal":"估算与逆运算检验","summary":"先把两个数取整得到大致范围，再计算并用反方向核对。估计能排除离谱答案；看起来接近，也可能算错一点。","reflection":"801与800都接近估计800，它们就都正确吗？","batch":"B11"},"checkpurpose":{"topicId":"mt_G3sVFQNCme","title":"大概够用，还是要精确","formal":"估算精度与情境要求","summary":"估计多细要看用途：粗看规模与核对小差别，需要的精度不同。实际付款要精确，估计预算可以取整。是否接近估计与是否精确相等是两种判断。","reflection":"同一批物品，先估预算与最后付款，为什么需要不同精度？","batch":"B11"}};
